      sha256 "35f58534998debb7c627d7a219841dcd8983e05e32cf95bb8dd1c52f447a46f8"
    end
    on_intel do
      url "https://github.com/EvanZhang008/open-walnut/releases/download/v0.6.6/open-walnut-0.6.6-darwin-x64.tar.gz", using: :nounzip
      sha256 "29db744d0a7b6ba1e9308f059955a2f564dbc5158f7ca43e4257a1259b2fcc40"
    end
  end

  on_linux do
    on_arm do
